package guidancecontent

import (
	"io/fs"

	"github.com/jaxxstorm/fed/internal/readiness"
)

// CPO builds overview drafts without treating Rev5 exclusions as 20x duties.
func CPO(rules, markdown fs.FS) (readiness.Package, error) {
	return communicationDraft(rules, markdown, "CPO", "certification-package-overview", 42, cpoRecipes, []communicationCapability{
		{"cpo-package-manifest", "Versioned certification package inputs", "Certification package owner", "Locate the service package and overview, accountable official, publication process, human-readable and JSON representations, and source-of-update history. Map applicable overview inputs to metadata, public information/service list/policies, resource inventory, flows/security categories, third-party resources, cryptographic modules and independent-assessment material.", "A versioned manifest identifies input owners, applicability decisions, exact source revisions, publication locations and gaps; nonapplicable linked rules are not silently imposed."},
	}, []string{"Certification Package", "Certification Data", "Certification Class", "FedRAMP Independent Assessment", "Persistently", "Information Resource", "Third-Party Information Resource", "Security Category"})
}

var cpoRecipes = map[string]communicationRecipe{
	"CPO-CSF-CPM": {purpose: "This is the Rev5 maintenance rule; the inventoried 20x profiles exclude it by certification type. Do not substitute its yearly or six-month maxima for the 20x class-specific cadence."},
	"CPO-CSO-MTD": {cap: "cpo-package-manifest", owner: "Certification package owner", purpose: "Make the overview attributable to an accountable official and a specific update event.", setup: "Identify the responsible and accountable official and the versioning/update process that populates overview metadata.", operate: "Populate the official's name, title and contact information, overview version, last-update date and time, and source of update. Reconcile these values across the human-readable and JSON overview.", records: "Published overview in both representations, accountable-official designation, version record, last-update timestamp and originating change/source record.", review: "Check each metadata field against its authoritative owner or update record and compare both overview formats. A file modification timestamp is not automatically the source of update.", scope: "The service's Certification Package Overview and its responsible/accountable official and update provenance.", timing: "Record the actual date and time of the last update and the version to which it applies; no numeric update interval is introduced by this metadata rule.", insufficient: "An overview filename or version number alone, a team inbox without an official's name/title, or update time without update source.", trigger: "event"},
	"CPO-CSO-OVR": {cap: "cpo-package-manifest", owner: "Certification package owner", purpose: "Publish a concise overview inside the certification package in human-readable and JSON forms, including every applicable linked-rule input.", setup: "Resolve applicability of CPO-CSO-MTD, CDS-CSO-PUB/SVC/IRP, MAS-CSO-IIR/FLO/TPR, CMU-CSO-CMD and IVV-CSO-ICP for the service's type/class. Map each applicable input to its source artifact and overview location.", operate: "Assemble both overview representations within the package from the mapped inputs. Include metadata, public information, service list, relevant policies, resource inventory, information flows/security categories, third-party resources, cryptographic modules and assessment materials where the linked rule applies. Retain explicit nonapplicability rationale for omitted linked-rule information.", records: "Published human-readable and JSON overview pair, package manifest showing inclusion, field-to-source and linked-rule applicability map, and the exact revisions of all applicable input artifacts.", review: "Compare semantic contents of both representations and trace each applicable linked-rule input to its underlying artifact. JSON parsing or schema success cannot establish completeness or correctness. The Rev5 note replaces the base SSP, not its appendices.", scope: "The entire offering's overview in its certification package, with applicability evaluated separately for every listed linked rule.", timing: "Bind overview versions and publication dates to their source revisions; package maintenance cadence is governed by the applicable maintenance rule, not invented here.", insufficient: "Only a PDF, only JSON, a schema-valid but empty object, or unqualified omission of linked-rule material.", trigger: "event"},
	"CPO-CSO-OSA": {cap: "cpo-package-manifest", owner: "Certification package owner and assessor liaison", purpose: "Include the assessor-supplied overall assessment summary in the overview for the selected class.", setup: "Obtain the overall independent-assessment summary supplied by the assessor under IVV-IAS-OSA and match it to the offering, assessment and certification class.", operate: "Include the assessor's overall summary in the Certification Package Overview, maintaining its attribution and linkage to the underlying independent assessment.", records: "Assessor-supplied summary revision, transmittal/provenance, assessment scope and period, and published overview showing the included summary.", review: "Compare the included text or material to the assessor-supplied summary and confirm the assessment and offering match. A provider-authored assurance statement is not a replacement.", scope: "The selected class's service overview and its corresponding independent assessment.", timing: "Retain assessment, summary-supply and overview-publication dates and revisions; no separate delivery deadline is stated here.", insufficient: "An assessor logo, a provider paraphrase without the supplied summary, or a summary for a different offering/assessment.", trigger: "event"},
	"CPO-CSX-CPM": {cap: "cpo-package-manifest", owner: "Certification package owner and automation owner", purpose: "Keep the complete 20x package current with service changes on the selected class's maintenance cadence, without imposing persistent human review of every artifact.", setup: "Connect package inputs to change events and establish class-specific maintenance scheduling, version comparison and stale/missing-input detection. Record known status and intentional interruptions for persistent activity.", operate: "Maintain package currency and completeness as changes occur, using automation where appropriate, and check the maximum interval in the selected class statement. Preserve Class A SHOULD with a documented weighed decision rather than upgrading it to MUST; the source does not expect human review of every material on that cadence.", records: "Package manifest and revision history, input-change events, automation runs or attributable manual updates, completeness/currency checks, stale-input findings and resolutions, selected class cadence, current status and interruption records.", review: "Compare actual service/input changes with published package revisions and maintenance intervals. A successful job that copied stale inputs is not proof of a current and complete package. Evaluate repetition and class cadence separately from human assessment activities.", scope: "The full FedRAMP Certification Package for the 20x offering, including all applicable artifacts and inherited input owners.", timing: "Use the exact selected class statement: Class A at least once every 3 months (SHOULD), B every month, C every 2 weeks, D every week (MUST). Persistency allows understood interruptions but does not erase explicit class-specific maxima.", insufficient: "A recent timestamp on an incomplete package, one automation success without input comparison, or a monthly schedule applied to Class C/D.", trigger: "recurring"},
}
